package com.bank.cli;

import java.io.BufferedReader;
import java.io.ByteArrayInputStream;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.math.BigDecimal;
import java.nio.charset.StandardCharsets;
import java.util.Scanner;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class AdminCliDemo {
    private static final Logger log = Logger.getLogger(AdminCliDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) throws Exception {
        // Simulated interactive input: an account seed, a name, then nothing.
        String onboardingInput = "2001\nRajesh Kumar\n";
        Scanner sc = new Scanner(new ByteArrayInputStream(
                onboardingInput.getBytes(StandardCharsets.UTF_8)), StandardCharsets.UTF_8);

        OnboardingService onboarding = new OnboardingService();
        Account created = onboarding.onboard(sc);
        log.info(() -> "Onboarded: " + created.getAccountId() + " / " + created.getHolderName());

        // Bulk import via BufferedReader — fast line reading.
        String txnFile = "TXN-1,SAV2001,45000.00\nTXN-2,CUR3001,12000.00\nTXN-3,SAV2001,30000.00\n";
        InputStream bulk = new ByteArrayInputStream(txnFile.getBytes(StandardCharsets.UTF_8));
        BulkImportService importer = new BulkImportService();
        long lines = importer.countAndSum(bulk);
        log.info(() -> "Bulk import processed " + lines + " transaction lines");

        // Secure password read (Console if present, BufferedReader fallback).
        AuthService auth = new AuthService();
        boolean ok = auth.authenticate("admin",
                new BufferedReader(new InputStreamReader(
                        new ByteArrayInputStream("S3cret!\n".getBytes(StandardCharsets.UTF_8)),
                        StandardCharsets.UTF_8)));
        log.info(() -> "Operator authenticated = " + ok);
    }
}

