class OnboardingService {
    private static final Logger log = Logger.getLogger(OnboardingService.class.getName());

    Account onboard(Scanner sc) {
        int seed = sc.nextInt();          // reads 2001 but leaves the newline
        sc.nextLine();                    // FIX: consume the dangling newline
        String name = sc.nextLine();      // now reads "Rajesh Kumar" correctly
        log.fine(() -> "Read seed=" + seed + ", name=" + name);
        String accountId = "SAV" + seed;
        return new Account(accountId, name, new BigDecimal("1000000.00"));
    }
}

