class BulkImportService {
    private static final Logger log = Logger.getLogger(BulkImportService.class.getName());

    // BufferedReader: buffered, line-oriented, fastest for bulk input.
    long countAndSum(InputStream in) throws java.io.IOException {
        long count = 0;
        BigDecimal total = BigDecimal.ZERO;
        try (BufferedReader br = new BufferedReader(
                new InputStreamReader(in, StandardCharsets.UTF_8))) {
            String line;
            while ((line = br.readLine()) != null) {
                if (line.isBlank()) continue;
                String[] parts = line.split(",");
                total = total.add(new BigDecimal(parts[2].trim()));
                count++;
            }
        }
        BigDecimal sum = total;
        log.info(() -> "Imported total = " + sum);
        return count;
    }
}

