class AuthService {
    private static final Logger log = Logger.getLogger(AuthService.class.getName());

    // Prefer System.console().readPassword (no echo, char[]); fall back to reader.
    boolean authenticate(String user, BufferedReader fallback) throws java.io.IOException {
        char[] password;
        java.io.Console console = System.console();
        if (console != null) {
            password = console.readPassword("Password for %s: ", user);
        } else {
            log.warning("No console attached — using fallback reader (test/IDE).");
            String line = fallback.readLine();
            password = line == null ? new char[0] : line.toCharArray();
        }
        boolean ok = new String(password).equals("S3cret!");
        java.util.Arrays.fill(password, '\0');   // wipe the secret from memory
        return ok;
    }
}

